1	package indexroom
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"reflect"
9		"strings"
10		"testing"
11	)
12	
13	// This file pins the behavior that the snapshot's JSON text is a
14	// serialization, not a wire format with one fixed layout. The same legal
15	// snapshot written with reordered object fields, added layout whitespace, or
16	// equivalent string escapes must restore the very same chain — same heights,
17	// hashes, parent links, and transaction order — while structural changes (a
18	// field written twice, the blocks array reversed) stay invalid and a rejected
19	// restore never touches the existing main chain.
20	
21	// uescape renders the code point r as it appears in JSON text: a \uXXXX
22	// escape inside the BMP, or the surrogate-pair form above it. It lets the
23	// hand-written snapshots spell an identifier differently from the literal
24	// form while denoting the same decoded string.
25	func uescape(r rune) string {
26		if r <= 0xFFFF {
27			return fmt.Sprintf("\\u%04x", r)
28		}
29		r -= 0x10000
30		high := 0xD800 + int(r>>10)
31		low := 0xDC00 + int(r&0x3FF)
32		return fmt.Sprintf("\\u%04x\\u%04x", high, low)
33	}
34	
35	// prettyPrint re-renders canonical snapshot text with two-space indentation
36	// and a trailing newline, using the standard library so no production code
37	// helps manufacture the "reshaped" input.
38	func prettyPrint(t *testing.T, canonical string) string {
39		t.Helper()
40		var buf bytes.Buffer
41		if err := json.Indent(&buf, []byte(canonical), "", "  "); err != nil {
42			t.Fatalf("setup: indent snapshot failed: %v", err)
43		}
44		buf.WriteByte('\n')
45		return buf.String()
46	}
47	
48	// shuffledV1Snapshot is a hand-written version-1 snapshot whose text departs
49	// from an export in every tolerated way at once:
50	//   - blocks precedes version at the top level (tip comes in between);
51	//   - the fields inside each block object appear in an unusual order;
52	//   - the same identifiers are written partly as equivalent \uXXXX escapes
53	//     instead of literal characters (g, h, 1, 中);
54	//   - whitespace is added throughout (newlines, spaces around ':' and inside
55	//     the empty txs array).
56	//
57	// Decoded, it is a two-block chain: h1/genesis with transactions
58	// ["tx-中","other","tx-中",""] at height 1, and h2/h1 with one more "tx-中"
59	// occurrence at height 2.
60	func shuffledV1Snapshot() string {
61		return "{\n  \"blocks\" : [\n" +
62			"    { \"txs\" : [ \"tx-" + uescape('中') + "\", \"other\", \"tx-中\", \"\" ],\n" +
63			"      \"parent\" : \"" + uescape('g') + "enesis\", \"hash\" : \"" + uescape('h') + "1\", \"height\" : 1 },\n" +
64			"    { \"parent\" : \"h" + uescape('1') + "\", \"txs\" : [ \"tx-" + uescape('中') + "\" ], \"height\" : 2, \"hash\" : \"h2\" }\n" +
65			"  ],\n  \"tip\" : 2,\n  \"version\" : 1\n}\n"
66	}
67	
68	// shuffledV2Snapshot is the version-2 counterpart: tip precedes blocks, the
69	// block fields are reordered (timestamp first in block 1, last in block 2),
70	// the block-1 time is null while block 2 carries a real zero, and escapes are
71	// mixed into the identifiers.
72	func shuffledV2Snapshot() string {
73		return "{\n  \"tip\" : 2,\n" +
74			"  \"blocks\" : [\n" +
75			"    { \"timestamp\" : null, \"hash\" : \"" + uescape('h') + "1\", \"parent\" : \"g\", \"height\" : 1, \"txs\" : [ \"a\", \"\" ] },\n" +
76			"    { \"height\" : 2, \"hash\" : \"h2\", \"parent\" : \"h" + uescape('1') + "\", \"txs\" : [\"b\"], \"timestamp\" : 0 }\n" +
77			"  ],\n  \"version\" : 2\n}\n"
78	}
79	
80	// buildReferenceChain builds through the ordinary Append API the chain the
81	// hand-written reshaped version-1 snapshot is meant to decode to. Building it
82	// independently keeps the parser under test from being the oracle for
83	// itself.
84	func buildReferenceChain() *Index {
85		index := New()
86		appendRef := func(height int64, hash, parent string, txs []string, time *int64) {
87			if err := index.Append(Block{Height: height, Hash: hash, Parent: parent, Txs: txs, Time: time}); err != nil {
88				panic(fmt.Sprintf("setup append at height %d: %v", height, err))
89			}
90		}
91		appendRef(1, "h1", "genesis", []string{"tx-中", "other", "tx-中", ""}, nil)
92		appendRef(2, "h2", "h1", []string{"tx-中"}, nil)
93		return index
94	}
95	
96	// requireSameChain fails unless got and want describe the same main chain:
97	// tip, per-height content (height, hash, parent, transactions in order,
98	// timestamp presence and value), and the hash-to-height index.
99	func requireSameChain(t *testing.T, got, want *Index) {
100		t.Helper()
101		if got.Tip != want.Tip {
102			t.Fatalf("tip=%d, want %d", got.Tip, want.Tip)
103		}
104		if len(got.Blocks) != len(want.Blocks) || len(got.ByHash) != len(want.ByHash) {
105			t.Fatalf("chain size: blocks=%d byHash=%d, want blocks=%d byHash=%d",
106				len(got.Blocks), len(got.ByHash), len(want.Blocks), len(want.ByHash))
107		}
108		for h := int64(1); h <= want.Tip; h++ {
109			g, ok := got.Blocks[h]
110			if !ok {
111				t.Fatalf("missing block at height %d after restore", h)
112			}
113			w := want.Blocks[h]
114			if g.Height != w.Height || g.Hash != w.Hash || g.Parent != w.Parent {
115				t.Fatalf("height %d: got %+v, want %+v", h, g, w)
116			}
117			if !reflect.DeepEqual(g.Txs, w.Txs) {
118				t.Fatalf("height %d txs=%q, want %q", h, g.Txs, w.Txs)
119			}
120			if (g.Time == nil) != (w.Time == nil) || (g.Time != nil && *g.Time != *w.Time) {
121				t.Fatalf("height %d time=%v, want %v", h, g.Time, w.Time)
122			}
123			if got.ByHash[w.Hash] != h {
124				t.Fatalf("by-hash lookup for %q = %d, want %d", w.Hash, got.ByHash[w.Hash], h)
125			}
126		}
127	}
128	
129	// requireTxQuery runs an exact-identifier query and checks the hit positions,
130	// total occurrence count, and count of blocks holding a match.
131	func requireTxQuery(t *testing.T, index *Index, id string, wantHits []TxHit, total, matchedBlocks int64) {
132		t.Helper()
133		page, err := index.QueryTxs(TxQuery{TxIDs: []string{id}})
134		if err != nil {
135			t.Fatalf("query %q failed: %v", id, err)
136		}
137		// A nil expectation means "no hits"; the scanner returns an empty
138		// non-nil slice, so compare emptiness rather than slice identity.
139		if (wantHits == nil && len(page.Hits) != 0) ||
140			(wantHits != nil && !reflect.DeepEqual(page.Hits, wantHits)) {
141			t.Fatalf("query %q hits=%+v, want %+v", id, page.Hits, wantHits)
142		}
143		if page.TotalMatches != total || page.MatchedBlocks != matchedBlocks {
144			t.Fatalf("query %q: total=%d blocks=%d, want total=%d blocks=%d",
145				id, page.TotalMatches, page.MatchedBlocks, total, matchedBlocks)
146		}
147	}
148	
149	func TestRestoreReshapedV1TextMatchesCanonicalChain(t *testing.T) {
150		index := New()
151		if err := index.Restore(strings.NewReader(shuffledV1Snapshot())); err != nil {
152			t.Fatalf("reshaped snapshot rejected: %v", err)
153		}
154		requireSameChain(t, index, buildReferenceChain())
155	
156		// Querying by the decoded identifier finds every occurrence at its
157		// original position: "tx-中" appears twice in block 1 and once in block 2,
158		// the empty identifier at position 3, and "other" at position 1.
159		requireTxQuery(t, index, "tx-中", []TxHit{
160			{Height: 1, BlockHash: "h1", TxID: "tx-中", Position: 0},
161			{Height: 1, BlockHash: "h1", TxID: "tx-中", Position: 2},
162			{Height: 2, BlockHash: "h2", TxID: "tx-中", Position: 0},
163		}, 3, 2)
164		requireTxQuery(t, index, "", []TxHit{
165			{Height: 1, BlockHash: "h1", TxID: "", Position: 3},
166		}, 1, 1)
167		requireTxQuery(t, index, "other", []TxHit{
168			{Height: 1, BlockHash: "h1", TxID: "other", Position: 1},
169		}, 1, 1)
170	
171		// Case and whitespace inside an identifier are part of the identifier;
172		// accepting text variants must not merge originally distinct ids.
173		for _, other := range []string{" tx-中", "tx-中 ", "TX-中", "tx-中x"} {
174			requireTxQuery(t, index, other, nil, 0, 0)
175		}
