342		for _, height := range []int64{5, 6} {
343			if _, ok := index.Blocks[height]; ok {
344				t.Fatalf("replaced height %d still present", height)
345			}
346		}
347		for _, gone := range []string{"h1", "h2", "h3", "h4", "h5", "h6"} {
348			if _, ok := index.ByHash[gone]; ok {
349				t.Fatalf("replaced hash %s still indexed", gone)
350			}
351		}
352		for _, hit := range after.Hits {
353			if hit.Height > 4 || strings.HasPrefix(hit.BlockHash, "h") {
354				t.Fatalf("removed-chain record leaked into post-restore page: %+v", hit)
355			}
356		}
357		if after.ToHeight != 4 || after.TotalMatches != 5 || after.MatchedBlocks != 2 {
