362	// While the snapshot is still being read the restore holds no lock: a first
363	// page issued then completes on the complete OLD chain, and the fragments
364	// already consumed by the parser have no effect on it. Once the read
365	// finishes and the replacement lands, the same query answers from the new
366	// chain.
367	func TestQueryTxsWhileRestoreStillReading(t *testing.T) {
368		index := buildRestoreQueryOldChain(t)
369		// Park the read just before the second block object: the first snapshot
370		// block has already been consumed, but the replacement is nowhere near
371		// applied and Restore holds no lock.
372		reader := newGatedReader(t, restoreTxNewSnapshot, `{"height":2`)
373	
374		restoreDone := make(chan error, 1)
375		go func() {
376			restoreDone <- index.Restore(reader)
377		}()
378		<-reader.entered
379	
380		page, err := index.QueryTxs(restoreTxQuery)
381		if err != nil {
382			t.Fatalf("query during snapshot read failed: %v", err)
383		}
384		if !reflect.DeepEqual(viewOf(page), viewOf(literalRestoreTxOldFirstPage())) {
385			t.Fatalf("query during snapshot read must see the complete old chain:\n%+v", page)
386		}
387		select {
388		case err := <-restoreDone:
389			t.Fatalf("restore returned while its input was still gated: %v", err)
390		default:
391		}
