393		close(reader.release)
394		if err := <-restoreDone; err != nil {
395			t.Fatalf("restore after release failed: %v", err)
396		}
397		page, err = index.QueryTxs(restoreTxQuery)
398		if err != nil {
399			t.Fatal(err)
400		}
401		if !reflect.DeepEqual(viewOf(page), viewOf(literalRestoreTxNewFirstPage())) {
