		"page too small": {PageSize: -1},
		"page too large": {PageSize: MaxPageSize + 1},
	} {
		if _, err := index.QueryTxs(query); !errors.Is(err, ErrInvalidArgument) {
			t.Errorf("%s: err=%v, want ErrInvalidArgument", name, err)
		}
