199	// TestQueryTxsDescMayResizePageBetweenPages changes the page size on every
200	// continuation; the walk must still resume exactly where the previous page
201	// ended, neither repeating nor skipping an occurrence.
202	func TestQueryTxsDescMayResizePageBetweenPages(t *testing.T) {
203		var blocks [][]string
204		for h := 0; h < 10; h++ {
205			blocks = append(blocks, []string{"a", "b", "a"})
206		}
