245	// TestQueryTxsContinuationRejectsMismatchedOrder: an ascending cursor may
246	// not drive a descending continuation or vice versa; both are argument
247	// errors returning no usable page, and the genuine cursor still works.
248	func TestQueryTxsContinuationRejectsMismatchedOrder(t *testing.T) {
249		index := txChain(t,
250			[]string{"a"},
251			[]string{"a"},
252			[]string{"a"},
253			[]string{"a"},
254		)
255		asc, err := index.QueryTxs(TxQuery{PageSize: 2})
256		if err != nil {
257			t.Fatal(err)
258		}
259		desc, err := index.QueryTxs(TxQuery{PageSize: 2, Order: OrderDesc})
260		if err != nil {
261			t.Fatal(err)
262		}
263	
264		mismatched := []TxQuery{
265			{PageSize: 2, Order: OrderDesc, Cursor: asc.NextCursor},
266			{PageSize: 2, Order: OrderAsc, Cursor: desc.NextCursor},
267			// The zero value explicitly chosen is still a mismatch for a desc cursor.
268			{PageSize: 2, Cursor: desc.NextCursor},
269		}
270		for i, query := range mismatched {
271			page, err := index.QueryTxs(query)
272			if !errors.Is(err, ErrInvalidArgument) {
273				t.Errorf("case %d: err=%v, want ErrInvalidArgument", i, err)
274			}
275			if len(page.Hits) != 0 || page.NextCursor != "" {
276				t.Errorf("case %d: mismatched-order call returned a usable page: %+v", i, page)
277			}
278		}
279	
280		// Direction-consistent continuations still work, as does omitting Order
281		// on an ascending cursor (OrderAsc is the zero value).
282		ascNext, err := index.QueryTxs(TxQuery{PageSize: 2, Cursor: asc.NextCursor})
283		if err != nil {
284			t.Fatalf("ascending continuation refused: %v", err)
285		}
286		if len(ascNext.Hits) != 2 {
287			t.Fatalf("unexpected asc page: %+v", ascNext)
288		}
289		descNext, err := index.QueryTxs(TxQuery{PageSize: 2, Order: OrderDesc, Cursor: desc.NextCursor})
290		if err != nil {
291			t.Fatalf("descending continuation refused: %v", err)
292		}
293		if len(descNext.Hits) != 2 {
294			t.Fatalf("unexpected desc page: %+v", descNext)
295		}
296	}
