298	// TestQueryTxsDescContinuationPinsTheRange: blocks appended after the first
299	// descending page never enter the pagination; an empty-cursor query is the
300	// only way to read them.
301	func TestQueryTxsDescContinuationPinsTheRange(t *testing.T) {
302		index := txChain(t,
303			[]string{"a"},
304			[]string{"a"},
305			[]string{"a"},
306		)
307		first, err := index.QueryTxs(TxQuery{PageSize: 2, Order: OrderDesc})
308		if err != nil {
309			t.Fatal(err)
310		}
311		if first.ToHeight != 3 {
312			t.Fatalf("pinned to=%d, want 3", first.ToHeight)
313		}
314		want1 := []TxHit{
315			{Height: 3, BlockHash: "h3", TxID: "a", Position: 0},
316			{Height: 2, BlockHash: "h2", TxID: "a", Position: 0},
317		}
318		if !reflect.DeepEqual(first.Hits, want1) {
319			t.Fatalf("first desc page=%v, want %v", first.Hits, want1)
320		}
321	
322		for _, height := range []int64{4, 5} {
323			block := Block{Height: height, Hash: fmt.Sprintf("h%d", height), Parent: fmt.Sprintf("h%d", height-1), Txs: []string{"a"}}
324			if err := index.Append(block); err != nil {
325				t.Fatal(err)
326			}
327		}
328	
329		pages := collectDescPages(t, index, TxQuery{PageSize: 2, Cursor: first.NextCursor})
330		var all []TxHit
331		for _, page := range pages {
332			if page.TotalMatches != 3 || page.MatchedBlocks != 3 || page.ToHeight != 3 {
333				t.Fatalf("desc continuation saw appended blocks: %+v", page)
334			}
335			all = append(all, page.Hits...)
336		}
337		want := []TxHit{{Height: 1, BlockHash: "h1", TxID: "a", Position: 0}}
338		if !reflect.DeepEqual(all, want) {
339			t.Fatalf("remaining desc hits=%v, want %v", all, want)
340		}
341	
342		// A fresh first-page descending query now starts at the new tip.
343		fresh, err := index.QueryTxs(TxQuery{PageSize: 2, Order: OrderDesc})
344		if err != nil {
345			t.Fatal(err)
346		}
347		if fresh.ToHeight != 5 || fresh.TotalMatches != 5 || fresh.Hits[0].Height != 5 {
348			t.Fatalf("fresh desc query did not pick up appended blocks: %+v", fresh)
349		}
350	}
