380	// TestQueryTxsDescEquivalentFilterAndRange applies the same
381	// equivalence rules as ascending: reordered/duplicate ids and verbatim
382	// request bounds describe the same continuation.
383	func TestQueryTxsDescEquivalentFilterAndRange(t *testing.T) {
