407	// TestQueryTxsDescIgnoresTimestamps: ordering depends only on height and
408	// position, whether block times are missing, equal, or decrease with height.
409	func TestQueryTxsDescIgnoresTimestamps(t *testing.T) {
410		index := New()
411		times := []int64{100, 100, 50} // equal then decreasing with height
412		blocks := []Block{
