414			{Height: 2, Hash: "h2", Parent: "h1", Txs: []string{"a", "a"}, Time: &times[0]},
415			{Height: 3, Hash: "h3", Parent: "h2", Txs: []string{"a"}, Time: &times[1]},
416		}
417		for i, block := range blocks {
418			if i > 0 {
419				block.Time = &times[i]
420			}
421			if err := index.Append(block); err != nil {
