451	// TestScanPageLockedDescWindow is the descending twin of the ascending
452	// window contract: each offset slices the oracle's fully-reversed occurrence
453	// list, at most pageSize records retained, totals unchanged.
454	func TestScanPageLockedDescWindow(t *testing.T) {
455		var blocks [][]string
456		for h := 0; h < 40; h++ {
457			blocks = append(blocks, []string{
458				fmt.Sprintf("t%d", h%5),
459				"keep",
460				"keep",
461			})
462		}
463		index := txChain(t, blocks...)
464		const from, to = int64(1), int64(40)
465	
466		ascAll, matchedBlocks := referenceScan(index, from, to, nil)
467		wantAll := make([]TxHit, len(ascAll))
468		for i, hit := range ascAll {
469			wantAll[len(ascAll)-1-i] = hit
470		}
471	
472		for _, pageSize := range []int{1, 3, DefaultPageSize, MaxPageSize} {
473			var windowed []TxHit
474			for offset := int64(0); ; {
475				hits, total, gotBlocks := index.scanPageLocked(from, to, newTxFilter(nil), OrderDesc, offset, pageSize)
476				if total != int64(len(wantAll)) || gotBlocks != matchedBlocks {
477					t.Fatalf("pageSize=%d offset=%d: totals=%d/%d want %d/%d",
478						pageSize, offset, total, gotBlocks, len(wantAll), matchedBlocks)
479				}
480				if cap(hits) > pageSize {
481					t.Fatalf("pageSize=%d retained cap=%d", pageSize, cap(hits))
482				}
483				end := offset + int64(len(hits))
484				if end > int64(len(wantAll)) || !reflect.DeepEqual(hits, wantAll[offset:end]) {
485					t.Fatalf("pageSize=%d offset=%d: desc window mismatch", pageSize, offset)
486				}
487				windowed = append(windowed, hits...)
488				if len(hits) < pageSize {
489					break
490				}
491				offset = end
492			}
493			if !reflect.DeepEqual(windowed, wantAll) {
494				t.Fatalf("pageSize=%d: desc windows do not reconstruct the reversed list", pageSize)
495			}
496		}
497	}
