499	// TestQueryTxsDescConcurrentWithAppends mirrors the ascending concurrency
500	// test: descending readers always see one consistent pinned range and a
501	// strictly decreasing occurrence sequence.
502	func TestQueryTxsDescConcurrentWithAppends(t *testing.T) {
503		index := chain(t, Block{Height: 1, Hash: "h1", Parent: "genesis", Txs: []string{"tx-1"}})
504		stop := make(chan struct{})
505	
506		var writer sync.WaitGroup
507		writer.Add(1)
508		go func() {
509			defer writer.Done()
510			for height := int64(2); height <= 200; height++ {
511				select {
512				case <-stop:
513					return
514				default:
515				}
516				block := Block{
517					Height: height,
518					Hash:   fmt.Sprintf("h%d", height),
519					Parent: fmt.Sprintf("h%d", height-1),
520					Txs:    []string{fmt.Sprintf("tx-%d", height)},
521				}
522				if err := index.Append(block); err != nil {
523					return
524				}
525			}
526		}()
527	
528		var readers sync.WaitGroup
529		for reader := 0; reader < 4; reader++ {
530			readers.Add(1)
531			go func() {
532				defer readers.Done()
533				for round := 0; round < 20; round++ {
534					pages := 0
535					seen := 0
536					var total, matched, to int64 = -1, -1, -1
537					query := TxQuery{PageSize: 7, Order: OrderDesc}
538					var lastHeight int64 = 1 << 62
539					lastPosition := 1 << 30
540					for {
541						page, err := index.QueryTxs(query)
542						if err != nil {
543							t.Errorf("desc query failed during appends: %v", err)
544							return
545						}
546						if total == -1 {
547							total, matched, to = page.TotalMatches, page.MatchedBlocks, page.ToHeight
548						} else if page.TotalMatches != total || page.MatchedBlocks != matched || page.ToHeight != to {
549							t.Errorf("desc stats changed mid-pagination: %+v", page)
550							return
551						}
552						for _, hit := range page.Hits {
553							if hit.Height > lastHeight || (hit.Height == lastHeight && hit.Position >= lastPosition) {
554								t.Errorf("desc hits out of order after (%d,%d): %+v", lastHeight, lastPosition, hit)
555								return
556							}
557							lastHeight, lastPosition = hit.Height, hit.Position
558						}
559						seen += len(page.Hits)
560						pages++
561						if page.NextCursor == "" {
562							break
563						}
564						query.Cursor = page.NextCursor
565					}
566					if int64(seen) != total {
567						t.Errorf("desc paginated %d hits over %d pages, total says %d", seen, pages, total)
568						return
569					}
570				}
571			}()
572		}
573		readers.Wait()
574		close(stop)
575		writer.Wait()
576	}
