297		if idx.Blocks[1].Time != nil || idx.Blocks[3].Time != nil {
298			t.Fatalf("heights 1 and 3 must still lack timestamps: %v %v",
299				idx.Blocks[1].Time, idx.Blocks[3].Time)
300		}
301	
302		query.Cursor = page1.NextCursor
303		page, err := idx.QueryTxs(query)
304		if !errors.Is(err, ErrQueryChanged) {
305			t.Fatalf("continuation err=%v, want ErrQueryChanged", err)
306		}
307		if errors.Is(err, ErrInvalidArgument) {
308			t.Fatalf("in-range data change reported as ErrInvalidArgument: %v", err)
309		}
310		if !reflect.DeepEqual(page, TxPage{}) {
311			t.Fatalf("changed continuation must return no hits, cursor, or stats, got %+v", page)
312		}
313	
314		// Repeating the stale cursor fails identically: the height-1 occurrences
315		// the old page 2 would have returned are byte-identical data, but they
316		// must never be stitched onto the old first page.
317		page, err = idx.QueryTxs(query)
318		if !errors.Is(err, ErrQueryChanged) || !reflect.DeepEqual(page, TxPage{}) {
319			t.Fatalf("repeated stale cursor: err=%v page=%+v, want ErrQueryChanged and a zeroed page", err, page)
320		}
321	
322		// The index itself is healthy: an empty-cursor first page on the restored
323		// chain succeeds, sees the unchanged transaction occurrences, and still
324		// reports the fixed-range totals over data that did change.
325		fresh, err := idx.QueryTxs(descRestoreQuery())
326		if err != nil {
327			t.Fatalf("fresh first page after restore failed: %v", err)
328		}
329		if !reflect.DeepEqual(fresh.Hits, descRestoreWantPage1) {
330			t.Fatalf("fresh page1 hits=%v, want %v", fresh.Hits, descRestoreWantPage1)
331		}
332		requireDescRestoreRangeStats(t, fresh)
333		if fresh.NextCursor == "" {
334			t.Fatal("fresh first page must carry a continuation cursor")
335		}
336	}
337	
338	// Timestamps changing only ABOVE the pinned range are invisible to the old
339	// cursor: the in-range content stays identical and the restored tip still
340	// covers height 3, so the descending walk continues with the same remaining
341	// records and fixed-range statistics. A matching transaction sitting in an
342	// out-of-range block must not leak in.
343	func TestQueryTxsDescCursorSurvivesOutOfRangeTimestampRestore(t *testing.T) {
344		t4, t5 := int64(100), int64(200)
345		blocks := append(descRestoreSpecBlocks(nil, nil, nil),
346			// Height 4 even carries a matching "a" outside the pinned [1,3] range.
347			Block{Height: 4, Hash: "g4", Parent: "g3", Txs: []string{"a"}, Time: &t4},
348			Block{Height: 5, Hash: "g5", Parent: "g4", Txs: []string{"z"}, Time: &t5},
349		)
