351	
352		query := descRestoreQuery() // explicitly pins [1,3] despite the tip being 5
353		page1, err := idx.QueryTxs(query)
354		if err != nil {
355			t.Fatalf("first page failed: %v", err)
356		}
357		if !reflect.DeepEqual(page1.Hits, descRestoreWantPage1) {
358			t.Fatalf("page1 hits=%v, want %v", page1.Hits, descRestoreWantPage1)
359		}
360		requireDescRestoreRangeStats(t, page1)
361		if page1.NextCursor == "" {
362			t.Fatal("page1 must carry a continuation cursor")
363		}
364	
365		// Restore keeps heights 1..3 byte-identical (still missing timestamps) and
366		// changes only the timestamps of heights 4 and 5; the tip stays at 5 and
367		// still covers the pinned range.
368		const aboveRangeTimesChanged = `{"version":2,"tip":5,"blocks":[
369			{"height":1,"hash":"g1","parent":"genesis","txs":["a","b","a"],"timestamp":null},
370			{"height":2,"hash":"g2","parent":"g1","txs":["a","c"],"timestamp":null},
371			{"height":3,"hash":"g3","parent":"g2","txs":["b","a"],"timestamp":null},
372			{"height":4,"hash":"g4","parent":"g3","txs":["a"],"timestamp":777},
373			{"height":5,"hash":"g5","parent":"g4","txs":["z"],"timestamp":888}
374		]}`
375		if err := idx.Restore(strings.NewReader(aboveRangeTimesChanged)); err != nil {
376			t.Fatalf("out-of-range timestamp restore rejected: %v", err)
377		}
378		if idx.Tip != 5 {
379			t.Fatalf("tip=%d, want 5 so the pinned range [1,3] stays covered", idx.Tip)
380		}
381		if got := idx.Blocks[4].Time; got == nil || *got != 777 {
382			t.Fatalf("height 4 time=%v, want 777", got)
383		}
384		if got := idx.Blocks[5].Time; got == nil || *got != 888 {
385			t.Fatalf("height 5 time=%v, want 888", got)
386		}
387		if idx.Blocks[1].Time != nil || idx.Blocks[2].Time != nil || idx.Blocks[3].Time != nil {
388			t.Fatal("in-range timestamps must remain missing after the restore")
389		}
